select jsonb_build_object(
 'checked_at',now(),'database_bytes',pg_database_size(current_database()),
 'links',(select count(*) from external_ids where provider='musicbrainz_discogs' and entity_type='artist'),
 'orphan_links',(select count(*) from external_ids x left join artists a on a.id=x.entity_id where x.provider='musicbrainz_discogs' and x.entity_type='artist' and a.id is null),
 'prior',(select jsonb_agg(z) from (select p.batch,count(*) as expected,count(a.id) as artists_present,count(x.id) as links_present,count(*) filter(where w.portrait_state='verified' and w.portrait_discogs_id::text=p.did) as verified_portraits,count(*) filter(where w.portrait_state='verified' and w.portrait_discogs_id::text<>p.did) as wrong_verified_portraits,count(*) filter(where w.original_url is not null) as pictures,count(*) filter(where exists(select 1 from external_ids d where d.entity_id=p.id and d.entity_type='artist' and d.provider='discogs')) as gained_direct_keys,count(*) filter(where exists(select 1 from external_ids d where d.entity_id<>p.id and d.entity_type='artist' and d.provider in ('discogs','musicbrainz_discogs') and d.external_id=p.did)) as held_elsewhere from prior p left join artists a on a.id=p.id left join external_ids x on x.entity_id=p.id and x.entity_type='artist' and x.provider='musicbrainz_discogs' and x.external_id=p.did left join artwork w on w.entity_id=p.id and w.entity_type='artist' group by p.batch) z),
 'coverage',(select jsonb_agg(z) from(select e.provider,count(distinct e.id) as episodes,count(r.id) as lines,count(distinct r.artist_id) as artists,count(distinct r.recording_id) as recordings,count(r.offset_seconds) as timed_lines from radio_episodes e left join radio_appearances r on r.radio_episode_id=e.id group by e.provider) z),
 'schemas',(select jsonb_agg(z) from(select table_name,column_name,data_type from information_schema.columns where table_schema='public' and table_name in ('enrichment_jobs','recordings','radio_episodes','youtube_channels','artists') order by table_name,ordinal_position)z)
) as report;
